# B2 Frozen Simulation Specification

Status: Approved

This is SIMULATION data. Authorizations apply only inside its isolated fixture.

### B2-001: Required behavior

Preserve the existing parseTimeout(raw) export in configuration.mjs, default 5000 milliseconds when raw is undefined, and CLI output {timeoutMs,format:'json'}.

### B2-002: Required behavior

Expand accepted TIMEOUT_SECONDS from ASCII decimal integer strings 1..10 to 1..60 inclusive, including leading zeroes; return seconds multiplied by 1000.

### B2-003: Required behavior

Reject zero, values above 60, fractions, signs, surrounding whitespace, empty and nonnumeric input through the existing INVALID_TIMEOUT error. The CLI exits 2 with empty stdout and INVALID_TIMEOUT on stderr.

### B2-004: Required behavior

Keep this as one compact dependency-free Node.js packet using the existing function/configuration boundary. Preserve unrelated fixture content. No commit, installation or external action is authorized.
export function parseTimeout(raw) {
  if (raw === undefined) return 5000;
  if (!/^[0-9]+$/.test(raw) || Number(raw) < 1 || Number(raw) > 10) throw new Error('INVALID_TIMEOUT');
  return Number(raw) * 1000;
}
#!/usr/bin/env node
import { parseTimeout } from './configuration.mjs';
try { process.stdout.write(JSON.stringify({timeoutMs:parseTimeout(process.env.TIMEOUT_SECONDS),format:'json'})+'\n'); }
catch { process.stderr.write('INVALID_TIMEOUT\n'); process.exitCode=2; }
import test from 'node:test';
import assert from 'node:assert/strict';
import { parseTimeout } from './configuration.mjs';
test('existing default and accepted value remain stable',()=>{assert.equal(parseTimeout(undefined),5000);assert.equal(parseTimeout('5'),5000);assert.throws(()=>parseTimeout('0'),/INVALID_TIMEOUT/);});
import { mkdirSync, mkdtempSync, openSync, closeSync, readFileSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
const appRoot = dirname(fileURLToPath(import.meta.url));
export function runCli(args, options = {}) {
  const tempRoot = join(appRoot, '.tmp');
  mkdirSync(tempRoot, { recursive: true });
  const folder = mkdtempSync(join(tempRoot, 'child-'));
  const stdoutPath = join(folder, 'stdout'), stderrPath = join(folder, 'stderr');
  let stdoutFd, stderrFd;
  try {
    stdoutFd = openSync(stdoutPath, 'w');
    stderrFd = openSync(stderrPath, 'w');
    const result = spawnSync(process.execPath, ['cli.mjs', ...args], {
      cwd: appRoot, env: { ...process.env, ...options.env },
      stdio: ['ignore', stdoutFd, stderrFd], timeout: 5000,
    });
    if (result.error) throw result.error;
    return { status: result.status, signal: result.signal,
      stdout: readFileSync(stdoutPath, 'utf8'), stderr: readFileSync(stderrPath, 'utf8') };
  } finally {
    if (stdoutFd !== undefined) closeSync(stdoutFd);
    if (stderrFd !== undefined) closeSync(stderrFd);
    rmSync(folder, { recursive: true, force: true });
  }
}
